{
  "description": "The creature is a quadrupedal, low-slung animal shown in right-facing profile walking on a flat light surface against a plain off-white background. Its body is robust and arched, almost entirely covered in large overlapping rounded scales that are brown with darker centers and tan edges, with irregular patches of larger pale pink speckled scales on the mid-flank, lower side and shoulder. It has an elongated pointed snout with a dark nostril at the tip, a small glossy black eye, and four thick limbs ending in clawed feet. A long, thick, tapering scaly tail extends to the left rear, and six pink fleshy stalks bearing dense feathery red-pink filaments protrude from the sides and top of the head and neck just behind the ear openings.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated and tapering to a rounded snout with a dark nostril at the tip, textured light tan-brown skin on the sides with fine whiskers near the nose, a small round glossy black eye with a pale lower eyelid, and small overlapping brown scales covering the top of the head and nape",
      "where": "at the far right end of the body, facing right"
    },
    {
      "part": "ears",
      "looks_like": "small dark circular openings with a slightly raised rim and a shallow depression behind the gill bases",
      "where": "on the side of the head just behind and slightly below the pink gill stalks, one clearly visible on the near side"
    },
    {
      "part": "gills",
      "looks_like": "six pink fleshy stalks with dense feathery red-pink filaments along their sides, three large stalks projecting outward from the near side of the neck and three smaller stalks projecting upward from the top and far side of the head and neck",
      "where": "clustered on the neck immediately behind the head, on both the near side and the top/far side"
    },
    {
      "part": "legs",
      "looks_like": "four short thick muscular legs with wrinkled textured skin, the upper portions partially covered with overlapping brown scales and the lower portions bare with pebbly skin",
      "where": "under the body, two front legs supporting the chest and two hind legs supporting the rear, all in a walking stance"
    },
    {
      "part": "feet",
      "looks_like": "broad feet with thick toes bearing curved light brown claws, the front feet showing three prominent claws each and the hind feet showing multiple blunt claws with scaly textured skin",
      "where": "at the distal ends of each leg resting on the ground surface"
    },
    {
      "part": "tail",
      "looks_like": "long thick at the base and tapering toward the tip, densely covered with overlapping brown scales matching the back",
      "where": "extending to the left from the rear of the body, partially visible at the left edge of the image"
    },
    {
      "part": "scales",
      "looks_like": "large overlapping rounded keratinous scales with dark brown centers and lighter tan-brown edges, giving a pangolin-like armor appearance",
      "where": "covering the dorsal surface, sides, tail, upper portions of all four limbs, and the top of the head and neck"
    },
    {
      "part": "markings",
      "looks_like": "irregular patches of larger pale pink scales with fine darker speckling, contrasting with the surrounding brown scales",
      "where": "on the upper mid-back, on the lower flank behind the front legs, and on the shoulder and lower neck around the gill bases"
    }
  ],
  "attached_objects": [],
  "animals": [
    "pangolin",
    "axolotl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
